function payerConfig() {
  const raw = (session && session.payers) || {};
  return {
    payers: Array.isArray(raw.payers) ? raw.payers : [],
    mode: raw.mode === 'even' ? 'even' : 'assigned',
    assignments: (raw.assignments && typeof raw.assignments === 'object') ? raw.assignments : {},
    paid_by: raw.paid_by || null,
  };
