function personKey(name) {
  return String(name == null ? 'Unlabelled' : name).split(/\s+/).filter(Boolean).join(' ').toLowerCase();
}

function payerPeople() {
  const names = new Map();
  ((session && session.orders) || []).forEach((order) => {
    const key = personKey(order.person);
    if (!names.has(key)) names.set(key, String(order.person || 'Unlabelled'));
  });
  (((session && session.costs) || {}).by_person || []).forEach((entry) => {
    const key = personKey(entry.person);
    if (!names.has(key)) names.set(key, String(entry.person || 'Unlabelled'));
  });
  return [...names.entries()].map(([key, name]) => ({ key, name }));
}

function payerShare(payer) {
  const split = (session && session.costs && session.costs.payer_split) || null;
  const row = split && (split.payers || []).find((entry) => entry.payer === payer);
  return row ? money(row.total) : money(0);
