function buildPayerBody(patch) {
  const config = payerConfig();
  const merged = { ...config, ...(patch || {}) };
  const listed = merged.payers.filter((name) => typeof name === 'string' && name.trim()).map((name) => name.trim());
  const assignments = {};
  Object.entries(merged.assignments || {}).forEach(([key, payer]) => {
    if (listed.includes(payer)) assignments[key] = payer;
  });
  const paidBy = listed.includes(merged.paid_by) ? merged.paid_by : (listed[0] || null);
  return { payers: listed, mode: merged.mode === 'even' ? 'even' : 'assigned', assignments, paid_by: paidBy };
}

async function updatePayers(patch, successMessage) {
  if (!session || session.status === 'closed') return;
  const body = buildPayerBody(patch);
