class PayerHttpTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temporary = tempfile.TemporaryDirectory()
        cls.original_dir = group_orders.SESSION_DIR
        cls.original_run_dir = runs.RUN_DIR
        group_orders.SESSION_DIR = Path(cls.temporary.name) / "group-orders"
        runs.RUN_DIR = Path(cls.temporary.name) / "runs"
        cls.httpd = ThreadingHTTPServer(("127.0.0.1", 0), server.Handler)
        cls.base = f"http://127.0.0.1:{cls.httpd.server_address[1]}"
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.httpd.shutdown()
        cls.httpd.server_close()
        group_orders.SESSION_DIR = cls.original_dir
        runs.RUN_DIR = cls.original_run_dir
        cls.temporary.cleanup()

    def request(self, method: str, path: str, payload=None, headers=None):
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        request_headers = dict(headers or {})
        if payload is not None:
            request_headers["Content-Type"] = "application/json"
        request = urllib.request.Request(
            self.base + path, data=data, method=method, headers=request_headers)
        try:
            with urllib.request.urlopen(request, timeout=10) as response:
                return response.status, json.loads(response.read())
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read())

    def test_payers_endpoint_sets_and_clears_the_split(self):
        status, created = self.request("POST", "/api/group-orders", {
            "title": "Two teams tea", "organizer_name": "Mariam",
        })
        self.assertEqual(status, 201)
        room_id = created["session_id"]
        token = created["organizer_token"]
        headers = {"X-Organizer-Token": token}
        self.request("POST", f"/api/group-orders/{room_id}/orders", ORDER)

        status, updated = self.request("PATCH", f"/api/group-orders/{room_id}/payers", {
            "payers": ["Alice", "Bob"],
            "assignments": {"Bob": "Bob"},
            "paid_by": "Alice",
        }, headers)
        self.assertEqual(status, 200)
        split = updated["session"]["costs"]["payer_split"]
        self.assertEqual(split["paid_by"], "Alice")
        self.assertAlmostEqual(
            sum(row["total"] for row in split["payers"]),
            updated["session"]["costs"]["total"])

        status, denied = self.request("PATCH", f"/api/group-orders/{room_id}/payers", {
            "payers": ["Alice"],
        }, {"X-Organizer-Token": "wrong"})
        self.assertEqual(status, 403)

        status, bad = self.request("PATCH", f"/api/group-orders/{room_id}/payers", {
            "payers": ["Alice", "alice"],
        }, headers)
        self.assertEqual(status, 400)

        status, cleared = self.request("PATCH", f"/api/group-orders/{room_id}/payers", {
            "payers": [],
        }, headers)
        self.assertEqual(status, 200)
        self.assertNotIn("payer_split", cleared["session"]["costs"])


if __name__ == "__main__":
    unittest.main()"}
